import { map, Observable } from "rxjs";
import { WebSocket } from "ws";
import { DEV } from "./debug.mjs";
import { retryOnBackoff } from "./operators/backoff.mjs";
const SERVER_PING_INTERVAL = 40000;
export function socketRx(backoffConfig, socketUrl) {
    return retryOnBackoff(backoffConfig, (iteration) => new Observable((subscriber) => {
        // TODO: why is this never set?
        let pingTimer;
        function heartbeat() {
            clearTimeout(pingTimer);
            pingTimer = setTimeout(() => {
                console.log(`<server ping timeout>`);
                ws.terminate();
            }, SERVER_PING_INTERVAL + 5000);
        }
        // todo: adjustable ip
        const ws = new WebSocket(socketUrl, {
            perMessageDeflate: {
                zlibDeflateOptions: {
                    level: 6,
                    memLevel: 8,
                },
                zlibInflateOptions: {
                    chunkSize: 10 * 1024,
                },
                clientNoContextTakeover: true,
                serverNoContextTakeover: true,
                threshold: 1024,
            },
        });
        ws.binaryType = "arraybuffer";
        ws.on("ping", heartbeat);
        ws.addEventListener("open", () => {
            heartbeat();
            subscriber.next({
                type: "open",
                data: {
                    iteration,
                    socket: {
                        sendJson(msg) {
                            ws.send(JSON.stringify(msg));
                        },
                        ws,
                    },
                },
            });
        });
        ws.addEventListener("message", (event) => {
            heartbeat();
            const rawData = event.data;
            let data;
            if (typeof rawData === "string") {
                try {
                    data = JSON.parse(rawData);
                }
                catch (error) {
                    console.error(`Failure parsing json ${rawData}`);
                    subscriber.complete();
                    return;
                }
            }
            else if (Array.isArray(rawData)) {
                console.warn("BUFFER ARRAY");
                data = concatBuffers(rawData);
            }
            else {
                // arraybuffer
                data = rawData;
            }
            subscriber.next({
                type: "msg",
                data,
            });
        });
        ws.addEventListener("close", () => {
            if (pingTimer) {
                clearTimeout(pingTimer);
            }
            subscriber.complete();
        });
        ws.addEventListener("error", (event) => {
            DEV `socket error ${event.message}`;
            subscriber.complete();
        });
        return () => {
            if (pingTimer) {
                clearTimeout(pingTimer);
            }
            ws.terminate();
        };
    })).pipe(map((notification) => notification.kind === "N" ? notification.value : { type: "close" }));
}
function concatBuffers(buffers) {
    const length = buffers.reduce((sum, buf) => sum + buf.byteLength, 0);
    const concatenated = new Uint8Array(length);
    buffers.reduce((index, buf) => {
        const bytes = new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
        concatenated.set(bytes, index);
        return index + bytes.length;
    }, 0);
    return concatenated.buffer;
}
